-- dim_item is SCD2. Surrogate item_key is generated by the table (AUTOINCREMENT) for every new version.
-- 1. same-day correction: update the version that started today
UPDATE dim_item SET item_nm = s.item_nm, item_desc = s.item_desc, unit_of_measure_cd = s.uom_cd, subclass_key = sc.subclass_key, update_ts = CURRENT_TIMESTAMP
FROM silver_item s JOIN dim_subclass sc ON sc.subclass_id = s.subclass_id
WHERE s.run_date = {{ dt(ds) }} AND s.action_cd = 'CORRECT' AND dim_item.item_id = s.item_id AND dim_item.effective_start_dt = {{ dt(ds) }};

-- 2. a tracked attribute changed: close the open version the day before
UPDATE dim_item SET effective_end_dt = {{ dadd(dt(ds), -1) }}, active_flg = FALSE, update_ts = CURRENT_TIMESTAMP
FROM silver_item s
WHERE s.run_date = {{ dt(ds) }} AND s.action_cd = 'CHANGE' AND dim_item.item_id = s.item_id AND dim_item.effective_end_dt = {{ dt('9999-12-31') }};

-- 3. open a new version (the first version of an item starts 1900-01-01 so facts of any day find it)
INSERT INTO dim_item (item_id, item_nm, item_desc, unit_of_measure_cd, subclass_key, brand_key, supplier_key, effective_start_dt, effective_end_dt)
SELECT s.item_id, s.item_nm, s.item_desc, s.uom_cd, sc.subclass_key,
       (SELECT MIN(brand_key) FROM dim_brand WHERE brand_id = 'UNKNOWN'), (SELECT MIN(supplier_key) FROM dim_supplier WHERE supplier_id = 'UNKNOWN'),
       CASE WHEN s.action_cd = 'NEW' THEN {{ dt('1900-01-01') }} ELSE {{ dt(ds) }} END, {{ dt('9999-12-31') }}
FROM silver_item s JOIN dim_subclass sc ON sc.subclass_id = s.subclass_id
WHERE s.run_date = {{ dt(ds) }} AND s.action_cd IN ('NEW', 'CHANGE');
